css:
.bmcsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8eef6;
    background: linear-gradient(165deg, #0a1729 0%, #0f2238 55%, #122a44 100%);
    border-radius: 18px;
}

.bmcsim-container * {
    box-sizing: border-box;
}

.bmcsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #07111f 0%, #102844 60%, #16395e 100%);
    color: #f3f7fc;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1c3a5c;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
}

.bmcsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f5d98a;
}

.bmcsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f5d98a;
    background: rgba(245, 217, 138, 0.10);
    border: 1px solid rgba(245, 217, 138, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.bmcsim-subtitle {
    margin: 12px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c4d3e6;
}

.bmcsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6d2;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.bmcsim-period-counter #currentDay,
.bmcsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f5d98a;
}

.bmcsim-round-name {
    background: rgba(245, 217, 138, 0.12);
    color: #f5d98a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.bmcsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffb4a2;
    background: rgba(192, 57, 43, 0.18);
    border: 1px solid rgba(255, 120, 100, 0.35);
    padding: 4px 12px;
    border-radius: 999px;
}

.bmcsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.bmcsim-status-card {
    background: #112338;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1d3a5a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #2c7fb8;
}

.bmcsim-card-esg { border-top-color: #2fa37a; }
.bmcsim-card-green { border-top-color: #4eb86a; }
.bmcsim-card-rorwa { border-top-color: #e0a13b; }
.bmcsim-card-capital { border-top-color: #6a8fd4; }

.bmcsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa2bf;
}

.bmcsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f3f7fc;
}

.bmcsim-card-esg .bmcsim-value { color: #4fd1a0; }
.bmcsim-card-green .bmcsim-value { color: #6fdc88; }
.bmcsim-card-rorwa .bmcsim-value { color: #f0bd5e; }
.bmcsim-card-capital .bmcsim-value { color: #93b4f0; }

.bmcsim-sublabel {
    font-size: 0.75rem;
    color: #7f97b4;
    line-height: 1.35;
}

.bmcsim-card-esg.bmcsim-target .bmcsim-value { color: #6fdc88; }
.bmcsim-card-esg.bmcsim-fail .bmcsim-value { color: #ff8c7a; }
.bmcsim-card-green.bmcsim-target .bmcsim-value { color: #6fdc88; }
.bmcsim-card-green.bmcsim-fail .bmcsim-value { color: #ff8c7a; }
.bmcsim-card-rorwa.bmcsim-target .bmcsim-value { color: #6fdc88; }
.bmcsim-card-rorwa.bmcsim-fail .bmcsim-value { color: #ff8c7a; }
.bmcsim-card-capital.bmcsim-addon { border-top-color: #c0392b; }
.bmcsim-card-capital.bmcsim-addon .bmcsim-value { color: #ff8c7a; }

.bmcsim-origination-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #07111f;
    color: #f3f7fc;
    border: 1px solid #1d3a5a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.bmcsim-origination-bar #originationDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f5d98a;
}

.bmcsim-origination-bar.bmcsim-floor-breach #originationDisplay {
    color: #ff8c7a;
}

.bmcsim-briefing {
    display: flex;
    gap: 14px;
    background: #112338;
    border-left: 5px solid #f5d98a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #1d3a5a;
    border-left: 5px solid #f5d98a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.bmcsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.bmcsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f5d98a;
    margin-bottom: 6px;
}

.bmcsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cddcee;
}

.bmcsim-briefing-text strong { color: #6fdc88; }
.bmcsim-briefing-text em { color: #ffb4a2; font-style: italic; }

.bmcsim-controls {
    background: #112338;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1d3a5a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.bmcsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f5d98a;
    border-bottom: 2px solid #1d3a5a;
    padding-bottom: 8px;
}

.bmcsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d6e3f2;
    margin: 14px 0 6px;
}

.bmcsim-container select,
.bmcsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4a6e;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1c30;
    color: #eaf1fa;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.bmcsim-container select:focus,
.bmcsim-container input[type="number"]:focus {
    outline: none;
    border-color: #f5d98a;
    box-shadow: 0 0 0 3px rgba(245, 217, 138, 0.18);
}

.bmcsim-container select option {
    background-color: #0c1c30;
    color: #eaf1fa;
}

.bmcsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f5d98a;
}

.bmcsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6d2;
    margin-top: 4px;
}

.bmcsim-range-readout span:last-child {
    color: #f5d98a;
    font-weight: 800;
}

.bmcsim-hint {
    font-size: 0.8rem;
    color: #7f97b4;
    margin-top: 4px;
    line-height: 1.4;
}

.bmcsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.bmcsim-container .btn-primary {
    background: linear-gradient(135deg, #c79a35 0%, #f5d98a 100%);
    border: none;
    color: #0a1729;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(199, 154, 53, 0.32);
}

.bmcsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.bmcsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2a4a6e;
    color: #9fb6d2;
    background: transparent;
}

.bmcsim-coach {
    background: #07111f;
    color: #cddcee;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3a5a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.bmcsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f5d98a;
    margin-bottom: 8px;
}

.bmcsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.bmcsim-coach-body strong { color: #6fdc88; }
.bmcsim-coach-body em { color: #ffb4a2; font-style: italic; }

.bmcsim-history,
.bmcsim-chart {
    background: #112338;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3a5a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.bmcsim-history h3,
.bmcsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f5d98a;
}

.bmcsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cddcee;
}

.bmcsim-container table#usfHistoryTable th {
    background: #0c1c30;
    color: #f5d98a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1d3a5a;
}

.bmcsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #18304b;
}

.bmcsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0e2034;
}

.bmcsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .bmcsim-container {
        padding: 14px;
    }
    .bmcsim-header h1 {
        font-size: 1.7rem;
    }
    .bmcsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .bmcsim-value {
        font-size: 2rem;
    }
    .bmcsim-clock {
        margin-left: 0;
    }
    .bmcsim-period-counter {
        font-size: 0.88rem;
    }
    .bmcsim-origination-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .bmcsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.bmcsim-completion { padding: 8px 4px 4px; }
.bmcsim-cm-head { text-align: center; margin-bottom: 16px; }
.bmcsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4fd1a0; }
.bmcsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #9fe6c5; }
.bmcsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #eaf5ef; }
.bmcsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.bmcsim-cm-yes { background: rgba(79,209,160,0.16); color: #4fd1a0; border: 1px solid rgba(79,209,160,0.45); }
.bmcsim-cm-no { background: rgba(255,127,127,0.14); color: #ff9b9b; border: 1px solid rgba(255,127,127,0.5); }
.bmcsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.bmcsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(111,220,136,0.08); border: 1px solid rgba(111,220,136,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.bmcsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6fdc88; }
.bmcsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #93a9b5; text-transform: uppercase; letter-spacing: 0.03em; }
.bmcsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #eaf5ef; }
.bmcsim-cm-insights { margin: 0; padding-left: 20px; }
.bmcsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #cfe3d8; }

