(function() {
    'use strict';

    class BankingTomorrowAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Banking for Tomorrow`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (concept 1799).
            this.START_ESG = 58;          // weighted ESG score /100
            this.TARGET_ESG = 70;         // 2027 Charter target
            this.START_GREEN = 24;        // green/transition origination %
            this.TARGET_GREEN = 40;       // 2027 commitment
            this.START_RORWA = 0.9;       // return on RWA %
            this.TARGET_RORWA = 1.1;      // CFO hurdle
            this.ADDON_CAPITAL = 95;      // EUR 95M Pillar 2 add-on (+0.4pp CET1)
            this.ORIGINATION_FLOOR = 100; // EUR 100M keep-lending floor (decidable 4-loan deck sums to 137M; 150M was the full 8-loan-deck figure and is unreachable here)
            this.ARREARS_EXPOSURE = 145;  // EUR 145M at-risk legacy exposure
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    esg: this.START_ESG,
                    green: this.START_GREEN,
                    rorwa: this.START_RORWA,
                    capital: 0,            // EUR M of buffer added (+) or add-on triggered (−)
                    origination: 0,        // EUR M new origination committed in the deck round
                    addonTriggered: false,
                    floorBreached: false,
                    esgHistory: [this.START_ESG],
                    greenHistory: [this.START_GREEN],
                    rorwaHistory: [this.START_RORWA],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    screen: `taxonomy`,
                    priority: `arrears`,
                    rigour: 60,
                    cement: `conditions`,
                    plastics: `decline`,
                    solar: `conditions`,
                    agri: `conditions`,
                    spread: 20,
                    ecb: `evidence`,
                    cfo: `economics`,
                    ngo: `milestones`,
                    workout: `restructure`,
                    incentive: `balanced`,
                    governance: `secondline`,
                    mix: 40,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const read = (id) => { const el = document.getElementById(id); return el ? el.value : null; };

            if (round === 1) {
                const sc = read(`screenInput`); if (sc !== null) decisions.screen = sc;
                const pr = read(`priorityInput`); if (pr !== null) decisions.priority = pr;
                const rg = document.getElementById(`rigourInput`);
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const ce = read(`cementInput`); if (ce !== null) decisions.cement = ce;
                const pl = read(`plasticsInput`); if (pl !== null) decisions.plastics = pl;
                const so = read(`solarInput`); if (so !== null) decisions.solar = so;
                const ag = read(`agriInput`); if (ag !== null) decisions.agri = ag;
                const sp = document.getElementById(`spreadInput`);
                if (sp) decisions.spread = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.spread) || decisions.spread < -60 || decisions.spread > 60) {
                    warn(`warn_spread_range`); return false;
                }
            } else if (round === 3) {
                const ec = read(`ecbInput`); if (ec !== null) decisions.ecb = ec;
                const cf = read(`cfoInput`); if (cf !== null) decisions.cfo = cf;
                const ng = read(`ngoInput`); if (ng !== null) decisions.ngo = ng;
                const wo = read(`workoutInput`); if (wo !== null) decisions.workout = wo;
            } else if (round === 4) {
                const inc = read(`incentiveInput`); if (inc !== null) decisions.incentive = inc;
                const gv = read(`governanceInput`); if (gv !== null) decisions.governance = gv;
                const mx = document.getElementById(`mixInput`);
                if (mx) decisions.mix = parseInt(mx.value, 10);
                if (!Number.isFinite(decisions.mix) || decisions.mix < 20 || decisions.mix > 60) {
                    warn(`warn_mix_range`); return false;
                }
                const cv = document.getElementById(`convictionInput`);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let esgDelta = 0, greenDelta = 0, rorwaDelta = 0, capitalDelta = 0, origination = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the book — strict taxonomy re-screening vs defending or quietly re-labelling.
                switch (d.screen) {
                    case `taxonomy`: esgDelta += 6; capitalDelta += 30; coachKey = `coach_r1_taxonomy`; break;
                    case `defend`: esgDelta -= 4; capitalDelta -= 25; coachKey = `coach_r1_defend`; break;
                    case `relabel`: esgDelta -= 2; greenDelta += 3; capitalDelta -= 40; coachKey = `coach_r1_relabel`; break;
                }

                // Priority: ESG never overrides default risk (Common Error / Decision Tree #6).
                switch (d.priority) {
                    case `arrears`: rorwaDelta += 0.10; capitalDelta += 18; coachKey = (d.screen === `taxonomy`) ? `coach_r1_sharp` : coachKey; break;
                    case `score`: rorwaDelta -= 0.15; coachKey = `coach_r1_scoreonly`; break;
                    case `profit`: esgDelta -= 5; rorwaDelta -= 0.20; coachKey = `coach_r1_profit`; break;
                }

                // Verification rigour: documented evidence is the antidote to greenwashing.
                if (d.rigour >= 60) { esgDelta += 4; capitalDelta += 12; }
                else if (d.rigour <= 25) { esgDelta -= 3; capitalDelta -= 18; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.screen === `taxonomy` && d.priority === `arrears`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The credit deck. Each loan moves all KPIs. Track which are approved for origination.
                const loans = {
                    cement:   { amt: 60, dec: d.cement },
                    plastics: { amt: 12, dec: d.plastics },
                    solar:    { amt: 25, dec: d.solar },
                    agri:     { amt: 40, dec: d.agri }
                };
                let approvedCount = 0, declinedCount = 0;

                // Cement — the transition case. Exclusion is the wrong call (Decision Tree #2).
                if (d.cement === `conditions`) { esgDelta += 5; greenDelta += 9; rorwaDelta += 0.10; origination += 60; approvedCount++; coachKey = `coach_r2_cement_cond`; }
                else if (d.cement === `approve`) { esgDelta -= 3; greenDelta += 4; rorwaDelta += 0.05; origination += 60; approvedCount++; coachKey = `coach_r2_cement_clean`; }
                else { greenDelta -= 6; rorwaDelta -= 0.05; declinedCount++; coachKey = `coach_r2_cement_decline`; }

                // Plastics — fails the screen. Approving clean is greenwashing/margin tunnel vision.
                if (d.plastics === `decline`) { esgDelta += 4; approvedCount += 0; declinedCount++; }
                else if (d.plastics === `conditions`) { esgDelta -= 2; rorwaDelta += 0.06; origination += 12; approvedCount++; coachKey = `coach_r2_plastics_cond`; }
                else { esgDelta -= 8; rorwaDelta += 0.12; origination += 12; approvedCount++; coachKey = `coach_r2_plastics_approve`; }

                // Solar — strong ESG, thin margin. Declining it is margin tunnel vision (Decision Tree #1).
                if (d.solar === `conditions`) { esgDelta += 6; greenDelta += 8; rorwaDelta += 0.02; origination += 25; approvedCount++; }
                else if (d.solar === `approve`) { esgDelta += 5; greenDelta += 8; rorwaDelta -= 0.05; origination += 25; approvedCount++; }
                else { esgDelta -= 5; greenDelta -= 5; declinedCount++; coachKey = `coach_r2_solar_decline`; }

                // Agri — weak governance. Conditions add value; clean approval imports the governance risk.
                if (d.agri === `conditions`) { esgDelta += 3; rorwaDelta += 0.05; origination += 40; approvedCount++; }
                else if (d.agri === `decline`) { esgDelta += 1; declinedCount++; }
                else { esgDelta -= 4; rorwaDelta += 0.04; origination += 40; approvedCount++; coachKey = `coach_r2_agri_approve`; }

                // Risk-based / sustainability-adjusted pricing. Flat (0) cross-subsidises (Decision Tree #4).
                const absSpread = Math.abs(d.spread);
                if (absSpread === 0) { rorwaDelta -= 0.12; coachKey = `coach_r2_flat`; }
                else if (d.spread > 0 && absSpread >= 20) { rorwaDelta += 0.12; esgDelta += 1; }
                else if (d.spread < 0 && absSpread >= 20) { rorwaDelta -= 0.04; greenDelta += 3; }
                else { rorwaDelta += 0.04; }

                ds.origination = origination;
                // Freezing the book breaches the EUR 100M floor (Decision Tree #5).
                if (origination < this.ORIGINATION_FLOOR) {
                    ds.floorBreached = true;
                    rorwaDelta -= 0.18; esgDelta -= 4; coachKey = `coach_r2_freeze`;
                } else {
                    ds.floorBreached = false;
                }
                if (declinedCount >= 3) coachKey = `coach_r2_freeze`;

                summaryKey = (d.cement === `conditions` && d.plastics !== `approve` && d.solar !== `decline` && origination >= this.ORIGINATION_FLOOR && absSpread > 0)
                    ? `sum_r2_good`
                    : (origination < this.ORIGINATION_FLOOR ? `sum_r2_frozen` : `sum_r2_weak`);
            } else if (round === 3) {
                // Defend the decisions — regulator, CFO, NGO + the arrears workout.
                switch (d.ecb) {
                    case `evidence`: esgDelta += 4; capitalDelta += 35; coachKey = `coach_r3_ecb_evidence`; break;
                    case `promise`: capitalDelta += 5; coachKey = `coach_r3_ecb_promise`; break;
                    case `dispute`: esgDelta -= 3; capitalDelta -= 40; coachKey = `coach_r3_ecb_dispute`; break;
                }

                switch (d.cfo) {
                    case `economics`: rorwaDelta += 0.10; coachKey = (d.ecb === `evidence`) ? `coach_r3_cfo_econ` : coachKey; break;
                    case `slogan`: rorwaDelta -= 0.10; coachKey = `coach_r3_cfo_slogan`; break;
                    case `volume`: rorwaDelta -= 0.05; esgDelta -= 2; coachKey = `coach_r3_cfo_volume`; break;
                }

                switch (d.ngo) {
                    case `milestones`: esgDelta += 4; greenDelta += 3; coachKey = (d.ecb === `evidence` && d.cfo === `economics`) ? `coach_r3_full` : coachKey; break;
                    case `exit`: greenDelta -= 6; esgDelta += 1; coachKey = `coach_r3_ngo_exit`; break;
                    case `dismiss`: esgDelta -= 4; coachKey = `coach_r3_ngo_dismiss`; break;
                }

                // Workout: ESG scoring is not a substitute for credit-risk management (Decision Tree #6).
                switch (d.workout) {
                    case `restructure`: rorwaDelta += 0.12; capitalDelta += 22; break;
                    case `ignore`: rorwaDelta -= 0.20; capitalDelta -= 30; coachKey = `coach_r3_workout_ignore`; break;
                    case `firesale`: rorwaDelta -= 0.10; capitalDelta -= 8; coachKey = `coach_r3_workout_firesale`; break;
                }

                summaryKey = (d.ecb === `evidence` && d.cfo === `economics` && d.ngo === `milestones` && d.workout === `restructure`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // The 2027 mandate path — incentives, governance, origination mix.
                switch (d.incentive) {
                    case `balanced`: esgDelta += 6; greenDelta += 7; rorwaDelta += 0.06; coachKey = `coach_r4_inc_balanced`; break;
                    case `volume`: esgDelta -= 5; greenDelta -= 5; rorwaDelta += 0.02; coachKey = `coach_r4_inc_volume`; break;
                    case `esgonly`: esgDelta += 4; greenDelta += 3; rorwaDelta -= 0.12; coachKey = `coach_r4_inc_esgonly`; break;
                }

                switch (d.governance) {
                    case `secondline`: esgDelta += 5; capitalDelta += 30; coachKey = (d.incentive === `balanced`) ? `coach_r4_governance` : coachKey; break;
                    case `guidance`: esgDelta += 1; capitalDelta += 5; coachKey = `coach_r4_gov_guidance`; break;
                    case `none`: esgDelta -= 4; capitalDelta -= 25; coachKey = `coach_r4_gov_none`; break;
                }

                // Origination mix: a credible, near-target commitment beats over-promising.
                const mixGap = Math.abs(d.mix - this.TARGET_GREEN);
                if (d.mix >= this.TARGET_GREEN && d.mix <= this.TARGET_GREEN + 5) { greenDelta += 8; esgDelta += 2; }
                else if (d.mix < this.TARGET_GREEN) { greenDelta += 2; coachKey = `coach_r4_mix_low`; }
                else if (d.mix > this.TARGET_GREEN + 10) { greenDelta += 3; rorwaDelta -= 0.08; coachKey = `coach_r4_mix_high`; }
                else { greenDelta += Math.max(2, 7 - mixGap); }

                esgDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.incentive === `balanced` && d.governance === `secondline` && d.mix >= this.TARGET_GREEN && d.mix <= this.TARGET_GREEN + 5) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas, bounding KPIs.
            ds.esg = Math.max(0, Math.min(100, Math.round((ds.esg + esgDelta) * 10) / 10));
            ds.green = Math.max(0, Math.min(100, Math.round((ds.green + greenDelta) * 10) / 10));
            ds.rorwa = Math.max(0, Math.round((ds.rorwa + rorwaDelta) * 100) / 100);
            ds.capital = Math.round(ds.capital + capitalDelta);

            // ECB add-on: weak ESG-risk governance (low capital buffer) triggers the −€95M Pillar 2 hit.
            if (ds.capital <= -50 && !ds.addonTriggered) {
                ds.addonTriggered = true;
            }

            ds.esgHistory.push(Math.round(ds.esg * 10) / 10);
            ds.greenHistory.push(Math.round(ds.green * 10) / 10);
            ds.rorwaHistory.push(Math.round(ds.rorwa * 100) / 100);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                esg: Math.round(ds.esg * 10) / 10,
                esgDelta: Math.round(esgDelta * 10) / 10,
                green: Math.round(ds.green * 10) / 10,
                greenDelta: Math.round(greenDelta * 10) / 10,
                rorwa: Math.round(ds.rorwa * 100) / 100,
                rorwaDelta: Math.round(rorwaDelta * 100) / 100,
                capital: ds.capital,
                addonTriggered: ds.addonTriggered,
                origination: ds.origination,
                floorBreached: ds.floorBreached,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

