        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const esg = Math.round(ds.esg * 10) / 10;
            const green = Math.round(ds.green * 10) / 10;
            const rorwa = Math.round(ds.rorwa * 100) / 100;
            const capital = ds.capital;
            const composite = Math.round(
                Math.min(100, (esg / this.TARGET_ESG) * 100) * 0.30 +
                Math.min(100, (green / this.TARGET_GREEN) * 100) * 0.25 +
                Math.min(100, (rorwa / this.TARGET_RORWA) * 100) * 0.25 +
                Math.min(100, Math.max(0, (capital + 95) / 1.9)) * 0.20
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitEsg && s.hitGreen && s.hitRorwa && !s.addon);
            const badge = met
                ? `<span class="bmcsim-cm-badge bmcsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="bmcsim-cm-badge bmcsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const addonBadge = s.addon
                ? ` <span class="bmcsim-cm-badge bmcsim-cm-no">` + T(`cm_addon`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const rorwaStr = (typeof s.rorwa === `number`) ? s.rorwa.toFixed(2) + `%` : String(s.rorwa || ``);
            const capStr = (typeof s.capital === `number`) ? (s.capital >= 0 ? `+` : ``) + Math.round(s.capital) + `bp` : String(s.capital || ``);
            const metrics = ``
                + `<div class="bmcsim-cm-metric"><span class="bmcsim-cm-mv">` + Math.round(s.esg || 0) + `</span><span class="bmcsim-cm-ml">` + T(`cm_m_esg`) + `</span></div>`
                + `<div class="bmcsim-cm-metric"><span class="bmcsim-cm-mv">` + Math.round(s.green || 0) + `%</span><span class="bmcsim-cm-ml">` + T(`cm_m_green`) + `</span></div>`
                + `<div class="bmcsim-cm-metric"><span class="bmcsim-cm-mv">` + rorwaStr + `</span><span class="bmcsim-cm-ml">` + T(`cm_m_rorwa`) + `</span></div>`
                + `<div class="bmcsim-cm-metric"><span class="bmcsim-cm-mv">` + capStr + `</span><span class="bmcsim-cm-ml">` + T(`cm_m_capital`) + `</span></div>`;
            return ``
                + `<div class="bmcsim-completion">`
                +   `<div class="bmcsim-cm-head">`
                +     `<div class="bmcsim-cm-score">` + score + `<span class="bmcsim-cm-score-max">/100</span></div>`
                +     `<div class="bmcsim-cm-grade">` + grade + ` ` + badge + addonBadge + `</div>`
                +   `</div>`
                +   `<div class="bmcsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="bmcsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="bmcsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const esg = Math.round(ds.esg * 10) / 10;
            const green = Math.round(ds.green * 10) / 10;
            const rorwa = Math.round(ds.rorwa * 100) / 100;
            const capital = ds.capital;

            const hitEsg = esg >= this.TARGET_ESG;
            const hitGreen = green >= this.TARGET_GREEN;
            const hitRorwa = rorwa >= this.TARGET_RORWA;
            const addon = ds.addonTriggered;
            const composite = Math.round(
                Math.min(100, (esg / this.TARGET_ESG) * 100) * 0.30 +
                Math.min(100, (green / this.TARGET_GREEN) * 100) * 0.25 +
                Math.min(100, (rorwa / this.TARGET_RORWA) * 100) * 0.25 +
                Math.min(100, Math.max(0, (capital + 95) / 1.9)) * 0.20
            );

            let performanceKey = `grade_greenwash`;
            if (hitEsg && hitGreen && hitRorwa && !addon && composite >= 85) performanceKey = `grade_real`;
            else if (hitEsg && hitGreen && hitRorwa && !addon) performanceKey = `grade_credible`;
            else if (hitRorwa && !hitEsg && !hitGreen) performanceKey = `grade_lostmandate`;
            else if (addon) performanceKey = `grade_addon`;
            else if ((hitEsg || hitGreen) && !hitRorwa) performanceKey = `grade_frozen`;
            else if (composite >= 60) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitEsg && hitGreen && hitRorwa && !addon) insights.push(window.mySimulation.t(`insight_made_real`));
            else if (hitRorwa && !hitEsg && !hitGreen) insights.push(window.mySimulation.t(`insight_margin_tunnel`));
            else if (addon) insights.push(window.mySimulation.t(`insight_addon`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!hitRorwa) insights.push(window.mySimulation.t(`insight_lowrorwa`));
            if (!hitEsg) insights.push(window.mySimulation.t(`insight_lowesg`));
            if (ds.floorBreached) insights.push(window.mySimulation.t(`insight_floor`));
            if (hitEsg && hitGreen && hitRorwa && !addon) insights.push(window.mySimulation.t(`insight_integrated`));

            return {
                esg: esg,
                green: green,
                rorwa: rorwa,
                capital: capital,
                hitEsg: hitEsg,
                hitGreen: hitGreen,
                hitRorwa: hitRorwa,
                addon: addon,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.addonTriggered) return window.mySimulation.t(`hint_addon`);
            if (ds.floorBreached) return window.mySimulation.t(`hint_floor`);
            if (ds.rorwa < this.TARGET_RORWA && state.currentPeriod >= 2) return window.mySimulation.t(`hint_pricing`);
            if (ds.esg < this.START_ESG) return window.mySimulation.t(`hint_esg`);
            if (ds.esg >= this.TARGET_ESG && ds.green >= this.TARGET_GREEN && ds.rorwa >= this.TARGET_RORWA) return window.mySimulation.t(`hint_strong`);
            return null;
        }

